    use aap:caps/types@0.1.0.{conversation-context, response-result};

    import aap:caps/kb-read@0.1.0;
    import aap:caps/tool-llm@0.1.0;

    export run: func(ctx: conversation-context) -> response-result;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;
use crate::aap::caps::tool_llm::Reply;

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds 512 characters".to_string(),
            });
        }

        let kb_results = kb_read::lookup(&ctx.question);

        let mut knowledge = ctx.knowledge.clone();
        knowledge.extend(kb_results);

        let system = "Answer the customer's question using the provided knowledge.";
        let prompt = format!(
            "Question: {}\nKnowledge: {}",
            ctx.question,
            knowledge.join("\n")
        );

        let reply = tool_llm::generate(system, &prompt);

        let text = match reply {
            Reply::Text(t) => t,
            Reply::Call(req) => {
                if req.tool == "lookup" {
                    let results = kb_read::lookup(&req.query);
                    results.join("\n")
                } else {
                    String::new()
                }
            }
        };

        ResponseResult::Ok(AgentResponse { text })
    }
}

export!(Node);
```

